use storyforge_domain::preset::{RegexPlacement, RegexScript, RegexScriptSource};
use storyforge_infra_regex::{RegexExecutionTarget, apply_regex_scripts_for_target};
fn make(name: &str, find: &str, replace: &str, flags: &str) -> RegexScript {
    RegexScript {
        id: name.into(),
        script_name: name.into(),
        find_regex: find.into(),
        replace_string: replace.into(),
        placement: RegexPlacement::Output,
        placement_codes: vec![2],
        source: RegexScriptSource::Scoped,
        disabled: false,
        flags: flags.into(),
        only_format_formatting: None,
        markdown_only: Some(true),
        prompt_only: Some(false),
        run_on_edit: None,
        substitute_regex: None,
        trim_strings: vec![],
        min_depth: None,
        max_depth: None,
    }
}
